    }
    let disposed = false;
    let objectUrl: string | null = null;
    void store.readPreview(projectId, slot.slotId).then((blob) => {
      if (disposed) return;
      if (blob === null || typeof URL.createObjectURL !== "function") { setFailed(slot); return; }
