                    {visible.map((entry) => <li key={entry.entryId}><div><span>{playerHistoryEventKind(entry.event)} · 归档</span><strong className="player-typography-text" lang={typography.locale}><PlayerRichText text={playerHistoryEventLabel(entry.event)} locale={typography.locale} /></strong></div></li>)}
                  </ol>}</PlayerHistoryPage>
                </section>
              ))}
            </>}</div>
          </aside>
        )}
        {additionalContentOpen && (
          <aside ref={additionalContentPanel} className="player-additional-content" role="dialog" aria-label="附加内容" aria-modal="true">
